css:
@page { size: 11in 8.5in landscape; margin: 0; }
.print-format { page-size: Custom; page-width: 1056px; page-height: 816px; margin-top: 0; margin-bottom: 0; margin-left: 0; margin-right: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Inter', Arial, sans-serif; color: #1a1a1a; -webkit-print-color-adjust: exact; }

.cert-page {
    position: relative;
    width: 11in;
    height: 8.5in;
    overflow: hidden;
    background: #ffffff;
    page-break-inside: avoid;
    break-inside: avoid;
}
.cert-frame {
    position: absolute;
    top: 0; left: 0;
    width: 11in;
    height: 8.5in;
    z-index: 0;
}
.cert-content {
    position: relative;
    z-index: 1;
    width: 10in;
    height: 7.5in;
    margin: 0.5in;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
}

.cert-logos { width: 100%; text-align: center; }
.cert-logos img { display: inline-block; vertical-align: middle; }
.cert-logo-ppt { height: 0.95in; margin-right: 0.4in; }
.cert-logo-ppt4ed { height: 0.65in; }
.cert-logo-ppt4ed-alone { height: 0.85in; }

.cert-title {
    margin-top: 0.5in;
    font-family: 'Playfair Display', 'Georgia', serif;
    font-size: 42pt;
    font-weight: 400;
    line-height: 1;
}

.cert-subtitle {
    margin-top: 0.35in;
    max-width: 8in;
    font-size: 11pt;
    font-weight: 400;
    letter-spacing: 0.08em;
    line-height: 1.6;
}

.cert-recipient-name {
    margin-top: 0.4in;
    font-size: 18pt;
    font-weight: 500;
    letter-spacing: 0.02em;
}

.cert-license {
    margin-top: 0.08in;
    font-size: 10pt;
    color: #555;
    letter-spacing: 0.04em;
}

.cert-preamble {
    margin-top: 0.25in;
    font-size: 12pt;
}

.cert-course-title {
    margin-top: 0.1in;
    max-width: 9in;
    font-size: 24pt;
    font-weight: 700;
    line-height: 1.25;
}

.cert-signatures {
    margin-top: 0.7in;
    width: 100%;
    text-align: center;
}
.cert-sig-block {
    display: inline-block;
    vertical-align: top;
    width: 3in;
    margin: 0 0.4in;
    text-align: center;
}
.cert-sig-cursive {
    font-family: 'Great Vibes', 'Allura', 'Apple Chancery', cursive;
    font-size: 32pt;
    font-weight: 400;
    line-height: 1.3;
    color: #222;
    padding: 6pt 4pt 4pt;
    white-space: nowrap;
}
.cert-sig-line {
    border-top: 1px solid #222;
    position: relative;
    margin: 2pt 0;
}
.cert-sig-line::before, .cert-sig-line::after {
    content: '';
    position: absolute;
    top: -4pt;
    width: 1px;
    height: 8pt;
    background: #222;
}
.cert-sig-line::before { left: 0; }
.cert-sig-line::after { right: 0; }
.cert-sig-name {
    font-size: 11pt;
    font-weight: 500;
    letter-spacing: 0.04em;
    padding-top: 4pt;
}

.cert-footer {
    margin-top: auto;
    width: 100%;
}
.cert-footer::after { content: ''; display: block; clear: both; }
.cert-footer-left {
    float: left;
    text-align: left;
    font-size: 10pt;
    letter-spacing: 0.06em;
    line-height: 1.6;
}
.cert-footer-right {
    float: right;
    text-align: right;
    font-size: 10pt;
    letter-spacing: 0.06em;
    line-height: 1.6;
}
.cert-footer-heading { font-weight: 500; }

html:
{%- set member = frappe.db.get_value("User", doc.member, ["full_name"], as_dict=True) -%}
{%- set course = frappe.db.get_value("LMS Course", doc.course, ["title", "name"], as_dict=True) if doc.course else None -%}
{%- set event = frappe.db.get_value("LMS Event", doc.event_name, ["title", "name", "venue", "start_date"], as_dict=True) if doc.event_name else None -%}
{%- set display_title = (course.title if course else (event.title if event else "")) -%}
{%- set is_event = True if doc.event_name else False -%}
{%- set instructor_parent = doc.event_name if is_event else doc.course -%}
{%- set instructor_parent_type = "LMS Event" if is_event else "LMS Course" -%}
{%- set instructors = frappe.get_all("Course Instructor", filters={"parent": instructor_parent, "parenttype": instructor_parent_type}, pluck="instructor", order_by="idx") if instructor_parent else [] -%}
{%- set approvals = frappe.get_all("CEU Discipline Link", filters={"parent": doc.course, "parenttype": "LMS Course"}, fields=["discipline", "approval_number"]) if doc.course else [] -%}
{%- set base_url = frappe.utils.get_url() -%}

<style>
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 100 900; font-display: block; src: url('data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Playfair Display'; font-style: normal; font-weight: 400 900; font-display: block; src: url('data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Great Vibes'; font-style: normal; font-weight: 400; font-display: block; src: url('data:font/woff2;base64,') format('woff2'); }
</style>

<div class="cert-page">
    <svg class="cert-frame" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 11 8.5" preserveAspectRatio="none" aria-hidden="true"><rect width="11" height="8.5" fill="#ffffff"/><rect x="0.25" y="0.25" width="10.5" height="8" rx="0.08" ry="0.08" fill="none" stroke="#1a1a1a" stroke-width="0.028"/><rect x="0.34" y="0.34" width="10.32" height="7.82" rx="0.05" ry="0.05" fill="none" stroke="#1a1a1a" stroke-width="0.007"/><g fill="none" stroke="#1a1a1a" stroke-width="0.006"><rect x="0.27" y="0.27" width="0.05" height="0.05" transform="rotate(45 0.295 0.295)"/><rect x="10.68" y="0.27" width="0.05" height="0.05" transform="rotate(45 10.705 0.295)"/><rect x="0.27" y="8.18" width="0.05" height="0.05" transform="rotate(45 0.295 8.205)"/><rect x="10.68" y="8.18" width="0.05" height="0.05" transform="rotate(45 10.705 8.205)"/></g></svg>

    <div class="cert-content">
        <div class="cert-logos">
            {% if is_event %}
            <img class="cert-logo-ppt" src="{{ base_url }}/assets/lms/images/ppt-logo.png">
            <img class="cert-logo-ppt4ed" src="{{ base_url }}/assets/lms/images/ppt4ed-logo.png">
            {% else %}
            <img class="cert-logo-ppt4ed-alone" src="{{ base_url }}/assets/lms/images/ppt4ed-logo.png">
            {% endif %}
        </div>

        <div class="cert-title">Certificate of Completion</div>

        <div class="cert-subtitle">PPT4ed in collaboration with Progressive Pediatric Therapy awards this certificate of attendance to:</div>

        <div class="cert-recipient-name">{{ member.full_name if member else doc.member_name }}</div>
        {% if doc.license_info %}<div class="cert-license">{{ doc.license_info }}</div>{% endif %}

        <div class="cert-preamble">for successful completion of the continuing education course entitled:</div>

        <div class="cert-course-title">{{ display_title }}</div>

        <div class="cert-signatures">
            {% for instructor in instructors %}
            {%- set inst = frappe.db.get_value("User", instructor, ["full_name", "signature_text"], as_dict=True) -%}
            {%- set sig_text = (inst.signature_text or inst.full_name) if inst else "" -%}
            <div class="cert-sig-block">
                <div class="cert-sig-cursive">{{ sig_text }}</div>
                <div class="cert-sig-line"></div>
                <div class="cert-sig-name">{{ inst.full_name if inst else "" }}</div>
            </div>
            {% endfor %}
        </div>

        <div class="cert-footer">
            <div class="cert-footer-left">
                {% if doc.ceu_hours %}<div class="cert-footer-heading">Approved: {{ (doc.ceu_hours | int) if (doc.ceu_hours == (doc.ceu_hours | int)) else doc.ceu_hours }} CE Hours{% if approvals %} for{% endif %}</div>{% endif %}
                {% for a in approvals %}
                <div>{{ a.discipline }} CE Approval #{{ a.approval_number or "PENDING" }}</div>
                {% endfor %}
            </div>
            <div class="cert-footer-right">
                <div>Date: {{ frappe.utils.format_date(doc.issue_date, "medium") }}</div>
                {% if is_event and event.venue %}<div>Location: {{ event.venue }}</div>{% endif %}
            </div>
        </div>
    </div>
</div>
